    """Discrete integer-grid solver. Angles integer degrees, sum N=180.
    theta must be an integer for this grid (use scaled N for half-degree etc).
    Returns list of WIN set sizes by depth, and the fixed point."""
    states = set()
    for a in range(1, N-1):
        for b in range(1, N-a):
            c = N - a - b
            if c >= 1:
                states.add(tuple(sorted((a,b,c))))
    states = list(states)

    def children(state, cutval):
        rest = list(state); rest.remove(cutval)
        b, c = rest[0], rest[1]
        a = cutval
        out = []
        for x in range(1, a):
            if N-b-x >= 1:
                C1 = tuple(sorted((x, b, N-b-x)))
            else:
                continue
            C2 = tuple(sorted((a-x, c, b+x)))
            out.append((C1, C2))
        return out

    child_cache = {}
    for s in states:
        for cv in set(s):
            child_cache[(s,cv)] = children(s, cv)

    WIN = [set() for _ in range(12)]
    s0 = set(s for s in states if theta in s)
    WIN[0] = s0
    fp_size = None
    for k in range(1, 12):
